 1→/**
 2→ * Recovery Tool E2E Test
 3→ *
 4→ * Seeds a vault with a file via SDK, then uses recovery.html to verify
 5→ * the IPFS-direct v2 blob recovery path works end-to-end.
 6→ *
 7→ * Requires: API + IPFS running locally (same as other web-e2e tests).
 8→ */
 9→import { test, expect } from '@playwright/test';
10→import {
11→  createTestAccount,
12→  deleteTestAccount,
13→  type TestAccount,
14→} from '../../sdk-e2e/src/fixtures/test-harness';
15→import { bytesToHex } from '@cipherbox/crypto';
16→
17→const API_URL = process.env.SDK_E2E_API_URL?.trim() || 'http://localhost:3000';
18→const WEB_URL = process.env.WEB_URL?.trim() || 'http://localhost:5173';
19→const IPFS_GATEWAY = process.env.RECOVERY_IPFS_GATEWAY?.trim() || 'http://localhost:8080';
20→// IPNS resolution via delegated routing service (Kubo can't resolve IPNS names published
21→// through it, and the CipherBox API requires auth). Derives from DELEGATED_ROUTING_URL
22→// used by the API, so it stays in sync if the service runs on a different port.
23→const IPNS_GATEWAY =
24→  process.env.RECOVERY_IPNS_GATEWAY?.trim() ||
25→  process.env.DELEGATED_ROUTING_URL?.trim() ||
26→  'http://localhost:3001';
27→
28→test.describe('Vault Recovery Tool', () => {
29→  let account: TestAccount;
30→  const testFileName = `recovery-test-${Date.now()}.txt`;
31→  const testFileContent = new TextEncoder().encode('CipherBox recovery test file content');
32→
33→  test.beforeAll(async () => {
34→    // Seed: create test account and upload a file
35→    account = await createTestAccount({
36→      apiUrl: API_URL,
37→      label: `recovery-e2e-${Date.now()}`,
38→      emailPrefix: 'recovery',
39→    });
40→
41→    // Upload a test file to the root folder
42→    await account.client.uploadFile(
43→      account.rootIpnsName,
44→      testFileContent,
45→      testFileName,
46→      'text/plain'
47→    );
48→
49→    // Brief wait for IPNS propagation to DB cache
50→    await new Promise((r) => setTimeout(r, 2000));
51→  });
52→
53→  test.afterAll(async () => {
54→    if (account) {
55→      account.client.destroy();
56→      account.privateKey.fill(0);
57→      account.rootFolderKey.fill(0);
58→      account.rootIpnsKeypair.privateKey.fill(0);
59→      await deleteTestAccount(account, API_URL);
60→    }
61→  });
62→
63→  test('recovers vault files via IPFS-direct v2 blob path', async ({ page }) => {
64→    // Navigate to recovery tool
65→    await page.goto(`${WEB_URL}/recovery.html`);
66→
67→    // Enter private key
68→    const privateKeyHex = bytesToHex(account.privateKey);
69→    await page.locator('[data-testid="recovery-key-input"]').fill(privateKeyHex);
70→
71→    // Set gateway URLs
72→    await page.locator('[data-testid="recovery-ipfs-gateway"]').clear();
73→    await page.locator('[data-testid="recovery-ipfs-gateway"]').fill(IPFS_GATEWAY);
74→
75→    await page.locator('[data-testid="recovery-ipns-gateway"]').clear();
76→    await page.locator('[data-testid="recovery-ipns-gateway"]').fill(IPNS_GATEWAY);
77→
78→    // Click start recovery
79→    await page.locator('[data-testid="recovery-start-btn"]').click();
80→
81→    // Wait for recovery to complete (progress log should show file name)
82→    // Recovery involves: IPNS resolution + IPFS fetch + v2 blob decrypt + folder traversal
83→    // This can take up to 60 seconds depending on IPNS propagation
84→    const progressLog = page.locator('[data-testid="recovery-progress-log"]');
85→
86→    // Wait for the progress log to contain the file name or a success indicator
87→    // The recovery tool logs each discovered file
88→    await expect(progressLog).toContainText(testFileName, {
89→      timeout: 60_000,
90→    });
91→
92→    // Verify the download button becomes visible (recovery succeeded)
93→    await expect(page.locator('[data-testid="recovery-download-btn"]')).toBeVisible({
94→      timeout: 10_000,
95→    });
96→  });
97→});
