  1→/**
  2→ * Vault Lifecycle Tests
  3→ *
  4→ * Tests vault initialization, duplicate init (409), get vault, export,
  5→ * config, and quota via raw API calls (pre-SDK level).
  6→ * Validates that the test harness creates working authenticated contexts.
  7→ */
  8→
  9→import { describe, it, expect, afterAll } from 'vitest';
 10→import { bytesToHex, deriveIpnsName } from '@cipherbox/crypto';
 11→import { initializeVault } from '@cipherbox/core';
 12→import {
 13→  createTestContext,
 14→  deleteTestAccount,
 15→  type TestContext,
 16→  API_URL,
 17→  testFetch,
 18→} from '../fixtures/test-harness';
 19→
 20→describe('Vault Lifecycle', () => {
 21→  let ctx: TestContext;
 22→
 23→  afterAll(async () => {
 24→    if (ctx) {
 25→      ctx.cleanup();
 26→      await deleteTestAccount(ctx);
 27→    }
 28→  });
 29→
 30→  it('should create a test context with valid client', async () => {
 31→    ctx = await createTestContext('vault-lifecycle');
 32→
 33→    expect(ctx.client).toBeTruthy();
 34→    expect(ctx.accessToken).toBeTruthy();
 35→    expect(ctx.publicKey.length).toBeGreaterThan(0);
 36→    expect(ctx.privateKey.length).toBeGreaterThan(0);
 37→    expect(ctx.rootIpnsName).toMatch(/^(k51|bafz)/);
 38→    expect(ctx.rootFolderKey.length).toBe(32);
 39→  });
 40→
 41→  it('should reject duplicate vault init (409)', async () => {
 42→    const vault = await initializeVault(ctx.privateKey);
 43→    const rootIpnsName = await deriveIpnsName(vault.rootIpnsKeypair.publicKey);
 44→
 45→    const res = await testFetch(`${API_URL}/vault/init`, {
 46→      method: 'POST',
 47→      headers: {
 48→        Authorization: `Bearer ${ctx.accessToken}`,
 49→        'Content-Type': 'application/json',
 50→      },
 51→      body: JSON.stringify({
 52→        ownerPublicKey: bytesToHex(ctx.publicKey),
 53→        rootIpnsName,
 54→      }),
 55→    });
 56→
 57→    expect(res.status).toBe(409);
 58→  });
 59→
 60→  it('should GET /vault and return vault data', async () => {
 61→    const res = await testFetch(`${API_URL}/vault`, {
 62→      headers: { Authorization: `Bearer ${ctx.accessToken}` },
 63→    });
 64→    expect(res.ok).toBe(true);
 65→
 66→    const data = await res.json();
 67→    expect(data.rootIpnsName).toBe(ctx.rootIpnsName);
 68→    expect(data.ownerPublicKey).toBe(bytesToHex(ctx.publicKey));
 69→  });
 70→
 71→  it('should GET /vault/export and return export data', async () => {
 72→    const res = await testFetch(`${API_URL}/vault/export`, {
 73→      headers: { Authorization: `Bearer ${ctx.accessToken}` },
 74→    });
 75→    expect(res.ok).toBe(true);
 76→
 77→    const data = await res.json();
 78→    expect(data.rootIpnsName).toBe(ctx.rootIpnsName);
 79→  });
 80→
 81→  it('should GET /vault/config and return config', async () => {
 82→    const res = await testFetch(`${API_URL}/vault/config`, {
 83→      headers: { Authorization: `Bearer ${ctx.accessToken}` },
 84→    });
 85→    expect(res.ok).toBe(true);
 86→
 87→    const data = await res.json();
 88→    expect(data.recycleBinRetentionDays).toBeTypeOf('number');
 89→    expect(data.recycleBinRetentionDays).toBeGreaterThan(0);
 90→  });
 91→
 92→  it('should GET /vault/quota and return usage data', async () => {
 93→    const res = await testFetch(`${API_URL}/vault/quota`, {
 94→      headers: { Authorization: `Bearer ${ctx.accessToken}` },
 95→    });
 96→    expect(res.ok).toBe(true);
 97→
 98→    const data = await res.json();
 99→    expect(data.usedBytes).toBeTypeOf('number');
100→    expect(data.limitBytes).toBeTypeOf('number');
101→    expect(data.limitBytes).toBeGreaterThan(0);
102→  });
103→
104→  it('should reject requests with invalid token', async () => {
105→    const res = await testFetch(`${API_URL}/vault`, {
106→      headers: { Authorization: 'Bearer invalid-token-here' },
107→    });
108→    expect(res.status).toBe(401);
109→  });
110→
111→  it('should reject test-login with wrong secret', async () => {
112→    const res = await testFetch(`${API_URL}/auth/test-login`, {
113→      method: 'POST',
114→      headers: { 'Content-Type': 'application/json' },
115→      body: JSON.stringify({
116→        email: 'bad-secret@example.com',
117→        secret: 'wrong-secret',
118→      }),
119→    });
120→    expect(res.status).toBe(401);
121→  });
122→});
