  1→/**
  2→ * SDK E2E Test Harness
  3→ *
  4→ * Creates authenticated CipherBoxClient instances backed by real API accounts.
  5→ * Extracted from packages/sdk/src/__tests__/integration.test.ts pattern.
  6→ *
  7→ * Each call to createTestContext() creates a unique user via /auth/test-login,
  8→ * initializes their vault, and returns a ready-to-use CipherBoxClient.
  9→ */
 10→
 11→import { CipherBoxClient } from '@cipherbox/sdk';
 12→import { initializeVault } from '@cipherbox/core';
 13→import { deriveIpnsName, hexToBytes, bytesToHex } from '@cipherbox/crypto';
 14→import { publishVaultKeyBlob } from '@cipherbox/sdk-core';
 15→import { createAxiosInstance } from '@cipherbox/api-client';
 16→
 17→const API_URL = process.env.SDK_E2E_API_URL ?? 'http://localhost:3000';
 18→const SECRET = process.env.SDK_E2E_SECRET ?? 'e2e-test-secret-do-not-use-in-production';
 19→const THROTTLE_BYPASS = process.env.THROTTLE_BYPASS_SECRET ?? '';
 20→
 21→/**
 22→ * Build default headers for fetch calls.
 23→ * Includes the throttle bypass header when THROTTLE_BYPASS_SECRET is set.
 24→ */
 25→function fetchHeaders(extra: Record<string, string> = {}): Record<string, string> {
 26→  const headers: Record<string, string> = { ...extra };
 27→  if (THROTTLE_BYPASS) {
 28→    headers['X-Throttle-Bypass'] = THROTTLE_BYPASS;
 29→  }
 30→  return headers;
 31→}
 32→
 33→/** Default headers for the api-client axios instance (throttle bypass). */
 34→function axiosDefaultHeaders(): Record<string, string> | undefined {
 35→  return THROTTLE_BYPASS ? { 'X-Throttle-Bypass': THROTTLE_BYPASS } : undefined;
 36→}
 37→
 38→/** Core account data returned by createTestAccount (shared between sdk-e2e and load tests). */
 39→export interface TestAccount {
 40→  client: CipherBoxClient;
 41→  accessToken: string;
 42→  publicKey: Uint8Array;
 43→  privateKey: Uint8Array;
 44→  rootIpnsName: string;
 45→  rootFolderKey: Uint8Array;
 46→  rootIpnsKeypair: { publicKey: Uint8Array; privateKey: Uint8Array };
 47→  email: string;
 48→}
 49→
 50→export interface TestContext extends TestAccount {
 51→  /** Destroy the client and zero key material */
 52→  cleanup: () => void;
 53→}
 54→
 55→export interface CreateAccountOptions {
 56→  apiUrl?: string;
 57→  secret?: string;
 58→  label: string;
 59→  emailPrefix?: string;
 60→}
 61→
 62→/**
 63→ * Create a test account with an initialized vault and CipherBoxClient.
 64→ * This is the shared core used by both sdk-e2e (createTestContext) and
 65→ * load tests (createPoolClient).
 66→ */
 67→export async function createTestAccount(opts: CreateAccountOptions): Promise<TestAccount> {
 68→  const apiUrl = opts.apiUrl ?? API_URL;
 69→  const secret = opts.secret ?? SECRET;
 70→  const prefix = opts.emailPrefix ?? 'sdk-e2e';
 71→  const email = `${prefix}-${opts.label}-${Date.now()}@example.com`;
 72→
 73→  // 1. Authenticate
 74→  const loginRes = await fetch(`${apiUrl}/auth/test-login`, {
 75→    method: 'POST',
 76→    headers: fetchHeaders({ 'Content-Type': 'application/json' }),
 77→    body: JSON.stringify({ email, secret }),
 78→  });
 79→  if (!loginRes.ok) {
 80→    throw new Error(`test-login failed (${loginRes.status}): ${await loginRes.text()}`);
 81→  }
 82→  const { accessToken, publicKeyHex, privateKeyHex } = await loginRes.json();
 83→  const publicKey = hexToBytes(publicKeyHex);
 84→  const privateKey = hexToBytes(privateKeyHex);
 85→
 86→  // Steps 2-4 wrapped in try/catch to clean up the test account on failure
 87→  try {
 88→    // 2. Initialize vault
 89→    const vault = await initializeVault(privateKey);
 90→    const rootIpnsName = await deriveIpnsName(vault.rootIpnsKeypair.publicKey);
 91→
 92→    // 3. Publish vault key blob to IPNS (rootFolderKey storage for recovery)
 93→    const axiosInstance = createAxiosInstance({
 94→      baseUrl: apiUrl,
 95→      getAccessToken: async () => accessToken,
 96→      defaultHeaders: axiosDefaultHeaders(),
 97→    });
 98→    await publishVaultKeyBlob({
 99→      userPrivateKey: privateKey,
100→      userPublicKey: publicKey,
101→      rootFolderKey: vault.rootFolderKey,
102→      ctx: { apiUrl, getAccessToken: async () => accessToken, axiosInstance },
103→    });
104→
105→    // 4. Register vault on server (v2: only ownerPublicKey + rootIpnsName, crypto lives in IPFS)
106→    const initRes = await fetch(`${apiUrl}/vault/init`, {
107→      method: 'POST',
108→      headers: fetchHeaders({
109→        Authorization: `Bearer ${accessToken}`,
110→        'Content-Type': 'application/json',
111→      }),
112→      body: JSON.stringify({
113→        ownerPublicKey: bytesToHex(publicKey),
114→        rootIpnsName,
115→      }),
116→    });
117→    if (!initRes.ok) {
118→      throw new Error(`vault/init failed (${initRes.status}): ${await initRes.text()}`);
119→    }
120→
121→    // 4. Create CipherBoxClient with instance-scoped axios (no singleton needed)
122→    const client = new CipherBoxClient({
123→      apiUrl,
124→      getAccessToken: async () => accessToken,
125→      vaultKeypair: { publicKey, privateKey },
126→      rootIpnsName,
127→      rootFolderKey: vault.rootFolderKey,
128→      defaultHeaders: axiosDefaultHeaders(),
129→    });
130→    client.registerFolder(rootIpnsName, vault.rootFolderKey, vault.rootIpnsKeypair, [], 0n);
131→
132→    return {
133→      client,
134→      accessToken,
135→      publicKey,
136→      privateKey,
137→      rootIpnsName,
138→      rootFolderKey: vault.rootFolderKey,
139→      rootIpnsKeypair: vault.rootIpnsKeypair,
140→      email,
141→    };
142→  } catch (err) {
143→    // Clean up partially provisioned account to avoid leaks
144→    await deleteTestAccount({ accessToken }, apiUrl);
145→    throw err;
146→  }
147→}
148→
149→/**
150→ * Create a fully-initialized test context (convenience wrapper over createTestAccount).
151→ */
152→export async function createTestContext(label: string): Promise<TestContext> {
153→  const account = await createTestAccount({ label });
154→  return { ...account, cleanup: () => account.client.destroy() };
155→}
156→
157→/**
158→ * Delete a test account (cleanup after tests).
159→ */
160→export async function deleteTestAccount(
161→  ctx: { accessToken: string },
162→  apiUrl = API_URL
163→): Promise<void> {
164→  try {
165→    const res = await fetch(`${apiUrl}/auth/account`, {
166→      method: 'DELETE',
167→      headers: fetchHeaders({
168→        Authorization: `Bearer ${ctx.accessToken}`,
169→        'Content-Type': 'application/json',
170→      }),
171→      body: JSON.stringify({ confirmation: 'DELETE' }),
172→    });
173→    if (!res.ok) {
174→      console.warn(`Account deletion failed (${res.status}): ${await res.text()}`);
175→    }
176→  } catch (err) {
177→    console.warn(`Account deletion error: ${(err as Error).message}`);
178→  }
179→}
180→
181→/**
182→ * fetch() wrapper that automatically injects the throttle bypass header.
183→ * Use instead of raw fetch() in test suites to avoid 429s.
184→ */
185→export function testFetch(url: string, init?: RequestInit): Promise<Response> {
186→  const headers = new Headers(init?.headers);
187→  if (THROTTLE_BYPASS) {
188→    headers.set('X-Throttle-Bypass', THROTTLE_BYPASS);
189→  }
190→  return fetch(url, { ...init, headers });
191→}
192→
193→export { API_URL, SECRET, fetchHeaders };
