    // =========================================================================
    let rootFolderKey = null;
    let privateKeyBytes = null;
    let recoveredFiles = [];
    let fileCount = 0;
    let errorCount = 0;
    let ipnsFailures = [];
    let directVaultKeyIpnsName = null; // Vault key blob IPNS (for fetching rootFolderKey)
    let directRootFolderIpnsName = null; // Root folder IPNS (for folder metadata traversal)

    // =========================================================================
    // Utility Functions
    // =========================================================================
    function hexToBytes(hex) {
      const clean = hex.startsWith('0x') ? hex.slice(2) : hex;
      if (clean.length % 2 !== 0) throw new Error('Invalid hex: odd length');
      const bytes = new Uint8Array(clean.length / 2);
      for (let i = 0; i < bytes.length; i++) {
        const b = parseInt(clean.substring(i * 2, i * 2 + 2), 16);
        if (Number.isNaN(b)) throw new Error('Invalid hex character');
        bytes[i] = b;
      }
