    // Crypto: Derive Vault IPNS Name from Private Key (HKDF)
    // =========================================================================
    const VAULT_HKDF_SALT = new TextEncoder().encode('CipherBox-v1');
    // Root folder IPNS (stores folder metadata {iv, data})
    const VAULT_FOLDER_HKDF_INFO = new TextEncoder().encode('cipherbox-vault-ipns-v1');
    // Vault KEY blob IPNS (stores ECIES-wrapped rootFolderKey) — NOT the root folder IPNS
    const VAULT_KEY_HKDF_INFO = new TextEncoder().encode('cipherbox-vault-key-ipns-v1');

    /**
