        { name: 'HKDF', hash: 'SHA-256', salt: VAULT_HKDF_SALT, info: hkdfInfo },
        keyMaterial, 256
      );
      const ed25519Seed = new Uint8Array(derivedBits);
      const ed25519PublicKey = await ed.getPublicKeyAsync(ed25519Seed);

