// Crypto: Decrypt File Metadata (v2 per-file IPNS records)
// =========================================================================
/**
 * Decrypt per-file metadata. Same format as folder metadata:
 * { iv: "hex", data: "base64" } encrypted with parent folderKey (AES-256-GCM).
 */
async function decryptFileMetadata(encryptedJson, folderKey) {
  const iv = hexToBytes(encryptedJson.iv);
  const ciphertext = base64ToBytes(encryptedJson.data);

  const cryptoKey = await crypto.subtle.importKey(
    'raw', folderKey, { name: 'AES-GCM' }, false, ['decrypt']
  );
  const plaintext = await crypto.subtle.decrypt(
    { name: 'AES-GCM', iv }, cryptoKey, ciphertext
  );

  return JSON.parse(new TextDecoder().decode(plaintext));
}

// =========================================================================
// IPNS Resolution
// =========================================================================
async function resolveIpns(ipnsName, gatewayUrl, ipfsGatewayUrl) {
  const maxRetries = 3;

  // Primary: IPFS gateway /ipns/ HEAD request (extracts CID from X-Ipfs-Roots header)
  const gwBase = ipfsGatewayUrl || gatewayUrl;
  try {
    const resp = await fetchWithTimeout(`${gwBase}/ipns/${ipnsName}`, { method: 'HEAD' });
    if (resp.ok) {
      const roots = resp.headers.get('X-Ipfs-Roots');
      if (roots) return roots.split(',')[0].trim();
    }
  } catch (e) {
    // Gateway doesn't support /ipns/ path, try delegated routing
  }

  // Fallback 1: Delegated routing API
  for (let attempt = 0; attempt < maxRetries; attempt++) {
    try {
      const url = `${gatewayUrl}/routing/v1/ipns/${ipnsName}`;
      const resp = await fetchWithTimeout(url, {
        headers: { 'Accept': 'application/json, application/vnd.ipfs.ipns-record' }
      });

      if (resp.ok) {
        // The delegated routing API can return the IPNS record in different formats
        // Try JSON first (application/json), then raw record
        const contentType = resp.headers.get('Content-Type') || '';

        if (contentType.includes('application/json')) {
          const json = await resp.json();
          // Extract CID from the record value
          if (json.record && json.record.value) {
            return extractCidFromValue(json.record.value);
          }
          if (json.value) {
            return extractCidFromValue(json.value);
          }
        }

        // For vnd.ipfs.ipns-record, the response is a binary IPNS record
        // We need to parse the CBOR/protobuf to extract the Value field
        const recordBytes = new Uint8Array(await resp.arrayBuffer());
        const cid = extractCidFromIpnsRecord(recordBytes);
        if (cid && /^(bafy|bafk|Qm)[a-zA-Z0-9]+$/.test(cid)) return cid;
      }
    } catch (e) {
      if (attempt < maxRetries - 1) {
        await sleep(1000 * Math.pow(2, attempt));
        continue;
      }
    }
  }

  // Fallback 2: CipherBox API (works when running locally alongside the app)
  const apiBase = window.location.origin.replace(/:\d+$/, ':3000');
  try {
    const url = `${apiBase}/ipns/resolve?ipnsName=${ipnsName}`;
    const resp = await fetchWithTimeout(url);
    if (resp.ok) {
      const json = await resp.json();
      if (json.cid) return json.cid;
      if (json.Path) return extractCidFromValue(json.Path);
    }
  } catch (e) {
    // CipherBox API not available
  }

  // Fallback 3: Kubo API name resolve
  const kuboBase = gatewayUrl.replace(/\/routing\/v1.*$/, '').replace(/\/$/, '');
  try {
    const url = `${kuboBase}/api/v0/name/resolve?arg=${ipnsName}`;
    const resp = await fetchWithTimeout(url, { method: 'POST' });
    if (resp.ok) {
      const json = await resp.json();
      if (json.Path) return extractCidFromValue(json.Path);
    }
  } catch (e) {
    // Kubo API not available or CORS blocked
  }

  throw new Error(`Failed to resolve IPNS name: ${truncate(ipnsName, 20)}. ` +
    'Ensure IPFS gateways are reachable or the CipherBox API is running on localhost:3000.');
}

function extractCidFromValue(value) {
  // Value is typically "/ipfs/bafy..." - extract the CID
  if (typeof value === 'string') {
    if (value.startsWith('/ipfs/')) return value.slice(6);
    return value;
  }
  // If it's bytes (from CBOR), decode as string
  if (value instanceof Uint8Array) {
    const str = new TextDecoder().decode(value);
    if (str.startsWith('/ipfs/')) return str.slice(6);
    return str;
  }
  throw new Error('Unexpected IPNS value format');
}

function extractCidFromIpnsRecord(recordBytes) {
  // IPNS records are protobuf-encoded.
  // The Value field is field number 2 (wire type 2 = length-delimited).
  // We need to find field 2 in the protobuf.
  try {
    let offset = 0;
    while (offset < recordBytes.length) {
      const fieldByte = recordBytes[offset];
      const fieldNumber = fieldByte >> 3;
      const wireType = fieldByte & 0x07;

      offset++;

      if (wireType === 2) {
        // Length-delimited
        let length = 0;
        let shift = 0;
        while (offset < recordBytes.length) {
          const b = recordBytes[offset++];
          length |= (b & 0x7f) << shift;
          if ((b & 0x80) === 0) break;
          shift += 7;
        }

        if (fieldNumber === 2) {
          // Value field - this is the IPFS path
          const valueBytes = recordBytes.slice(offset, offset + length);
          const value = new TextDecoder().decode(valueBytes);
          return extractCidFromValue(value);
        }

        offset += length;
      } else if (wireType === 0) {
        // Varint - skip
        while (offset < recordBytes.length && (recordBytes[offset] & 0x80) !== 0) offset++;
        offset++;
      } else {
        // Unknown wire type, bail
        break;
      }
    }
  } catch (e) {
    // Failed to parse protobuf
  }
  return null;
}

// =========================================================================
// IPFS Content Fetch
// =========================================================================
async function fetchFromIpfs(cid, ipfsGatewayUrl) {
  const maxRetries = 3;

  for (let attempt = 0; attempt < maxRetries; attempt++) {
    try {
      const url = `${ipfsGatewayUrl}/ipfs/${cid}`;
      const resp = await fetchWithTimeout(url, {}, 30000);
      if (resp.ok) {
        return new Uint8Array(await resp.arrayBuffer());
      }
      if (resp.status === 404) {
        throw new Error(`Content not found on IPFS: ${truncate(cid, 20)}`);
      }
      // Non-OK, non-404: retry or throw on last attempt
      if (attempt >= maxRetries - 1) {
        throw new Error(`IPFS gateway returned ${resp.status} for ${truncate(cid, 20)}`);
      }
    } catch (e) {
      if (e.message.includes('not found') || e.message.includes('gateway returned')) throw e;
      if (attempt < maxRetries - 1) {
        await sleep(1000 * Math.pow(2, attempt));
        continue;
      }
      throw new Error(`Failed to fetch from IPFS: ${truncate(cid, 20)}`);
    }
  }
}

function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

function escapeHtml(str) {
  const div = document.createElement('div');
  div.textContent = str;
  return div.innerHTML;
}

function fetchWithTimeout(url, options = {}, timeoutMs = 15000) {
  const controller = new AbortController();
  // Timer is NOT cleared on fetch resolve — it stays active through body reads
  // (resp.json(), resp.arrayBuffer()) so stalled bodies are also aborted.
  // controller.abort() is a no-op if the request already completed.
  setTimeout(() => controller.abort(), timeoutMs);
  return fetch(url, { ...options, signal: controller.signal });
}

