        await recoverFolder(child.ipnsName, subFolderKey, subPath, gatewayConfig);
      } catch (e) {
        log(`  ERROR recovering folder "${child.name}": ${e.message}`, 'error');
        errorCount++;
      }
    } else if (child.type === 'file') {
      // Validate FilePointer has required fileMetaIpnsName
      if (!child.fileMetaIpnsName) {
        log(`  ERROR: Invalid file child "${child.name}": missing fileMetaIpnsName (v1 format not supported)`, 'error');
        errorCount++;
        continue;
      }

      // -- FilePointer: resolve per-file IPNS to get file metadata --
      try {
        const filePath = path ? `${path}/${child.name}` : child.name;
        log(`Resolving file IPNS: ${child.name}...`, 'info');

        const fileIpnsName = child.fileMetaIpnsName;

        // a. Resolve file IPNS to get file metadata CID
        let fileMetaCid;
        try {
          fileMetaCid = await resolveIpns(fileIpnsName, gatewayConfig.ipnsGateway, gatewayConfig.ipfsGateway);
        } catch (resolveErr) {
          log(`  WARNING: File IPNS record may have expired for "${child.name}". ` +
              `IPNS name: ${truncate(fileIpnsName, 30)}. ` +
              `File content CID is not recoverable via IPNS.`, 'warn');
          ipnsFailures.push({ name: child.name, ipnsName: fileIpnsName });
          errorCount++;
          continue;
        }

        log(`  File metadata CID: ${truncate(fileMetaCid, 40)}`, 'info');

        // b. Fetch encrypted file metadata from IPFS
        const encFileMetaBytes = await fetchFromIpfs(fileMetaCid, gatewayConfig.ipfsGateway);
        const encFileMeta = JSON.parse(new TextDecoder().decode(encFileMetaBytes));

        // c. Decrypt file metadata with parent's folderKey
        const fileMeta = await decryptFileMetadata(encFileMeta, folderKey);

        // d. Extract file details from decrypted metadata
        const { cid: contentCid, fileKeyEncrypted, fileIv, size, encryptionMode } = fileMeta;

        log(`Downloading: ${filePath}... (${formatSize(size || 0)})`, 'info');

        // e. ECIES-decrypt file key
        const fileKey = await eciesDecrypt(privateKeyBytes, fileKeyEncrypted);

        // f. Fetch encrypted file from IPFS
        const encryptedFile = await fetchFromIpfs(contentCid, gatewayConfig.ipfsGateway);

        // g. Decrypt file content (using encryptionMode, defaults to GCM)
        const decryptedFile = await decryptFile(encryptedFile, fileKey, fileIv, encryptionMode);

        // Store for zip
        recoveredFiles.push({ path: filePath, data: decryptedFile });
        fileCount++;

        log(`  Decrypted: ${filePath} (${formatSize(decryptedFile.length)})`, 'success');

        // h. Process past versions if present
        if (Array.isArray(fileMeta.versions) && fileMeta.versions.length > 0) {
          log(`  Past versions: ${fileMeta.versions.length}`, 'info');

          for (let vi = 0; vi < fileMeta.versions.length; vi++) {
            const ver = fileMeta.versions[vi];
            const verDate = new Date(ver.timestamp).toISOString().slice(0, 19).replace('T', ' ');
            const verLabel = `v${fileMeta.versions.length - vi}`;

            try {
              log(`  Downloading ${verLabel} (${verDate}, ${formatSize(ver.size || 0)}, ${ver.encryptionMode || 'GCM'})...`, 'info');

              // Decrypt version's file key
              const verFileKey = await eciesDecrypt(privateKeyBytes, ver.fileKeyEncrypted);

              // Fetch version's encrypted content from IPFS
              const verEncrypted = await fetchFromIpfs(ver.cid, gatewayConfig.ipfsGateway);

              // Decrypt version content with appropriate mode
              const verDecrypted = await decryptFile(verEncrypted, verFileKey, ver.fileIv, ver.encryptionMode);

              // Build version filename: "file (v2).txt" pattern
              const verPath = buildVersionPath(filePath, verLabel);
              recoveredFiles.push({ path: verPath, data: verDecrypted });
              fileCount++;

              log(`  Decrypted: ${verPath} (${formatSize(verDecrypted.length)})`, 'success');
            } catch (verErr) {
              log(`  ERROR recovering ${verLabel} of "${child.name}": ${verErr.message}`, 'error');
              errorCount++;
            }
          }
        }
      } catch (e) {
        log(`  ERROR recovering file "${child.name}": ${e.message}`, 'error');
        errorCount++;
      }
    }
  }
}

function formatSize(bytes) {
  if (bytes < 1024) return bytes + ' B';
  if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' KB';
  return (bytes / (1024 * 1024)).toFixed(1) + ' MB';
}

/**
 * Build a versioned file path: "folder/file.txt" + "v2" -> "folder/file (v2).txt"
 * If no extension, appends the label: "folder/file" + "v2" -> "folder/file (v2)"
 */
function buildVersionPath(filePath, versionLabel) {
  const lastSlash = filePath.lastIndexOf('/');
  const dir = lastSlash >= 0 ? filePath.slice(0, lastSlash + 1) : '';
  const name = lastSlash >= 0 ? filePath.slice(lastSlash + 1) : filePath;

  const dotIndex = name.lastIndexOf('.');
  if (dotIndex > 0) {
    const base = name.slice(0, dotIndex);
    const ext = name.slice(dotIndex);
    return `${dir}${base} (${versionLabel})${ext}`;
  }
  return `${dir}${name} (${versionLabel})`;
}

