  try {
    // Parse private key (hex only — base64 not supported for v2 recovery)
    try {
      privateKeyBytes = hexToBytes(keyText);
    } catch {
      showError(1, 'Could not parse private key. Provide 32 bytes as 64 hex characters.');
      return;
    }

    if (privateKeyBytes.length !== 32) {
      showError(1, `Private key must be 32 bytes (got ${privateKeyBytes.length} bytes).`);
      privateKeyBytes = null;
      return;
    }

    const btn = document.getElementById('btn-start');
    btn.disabled = true;
    btn.textContent = '[ Deriving IPNS name... ]';

    // Derive both IPNS names from private key
    // Vault key blob IPNS: where the ECIES-wrapped rootFolderKey lives
    directVaultKeyIpnsName = await deriveIpnsNameFromKey(privateKeyBytes, VAULT_KEY_HKDF_INFO);
    // Root folder IPNS: where folder metadata lives (used for recovery traversal)
    directRootFolderIpnsName = await deriveIpnsNameFromKey(privateKeyBytes, VAULT_FOLDER_HKDF_INFO);

    // Show derived info
    const infoEl = document.getElementById('derived-info');
    let infoHtml = `<div class="field"><span class="field-name">Derived vaultKeyIpnsName:</span> <span class="field-value">${truncate(directVaultKeyIpnsName, 50)}</span></div>`;
    infoHtml += `<div class="field"><span class="field-name">Derived rootIpnsName:</span> <span class="field-value">${truncate(directRootFolderIpnsName, 50)}</span></div>`;
    infoHtml += `<div class="field"><span class="field-name">Recovery mode:</span> <span class="field-value">IPFS-direct (v2 vault key blob)</span></div>`;
    infoEl.innerHTML = infoHtml;
    infoEl.classList.add('visible');

    // Read gateways
    const ipnsGateway = document.getElementById('direct-ipns-gateway').value.trim().replace(/\/+$/, '');
    const ipfsGateway = document.getElementById('direct-ipfs-gateway').value.trim().replace(/\/+$/, '');

    btn.textContent = '[ Resolving vault... ]';

    // Fetch vault key blob via vault key IPNS name
    let blobBytes;
    try {
      const ipnsUrl = `${ipfsGateway}/ipns/${directVaultKeyIpnsName}`;
      const resp = await fetchWithTimeout(ipnsUrl, {}, 30000);
      if (!resp.ok) throw new Error(`Gateway returned ${resp.status}`);
      blobBytes = new Uint8Array(await resp.arrayBuffer());
    } catch (gatewayErr) {
      // Fallback: resolve IPNS separately then fetch content
      const cid = await resolveIpns(directVaultKeyIpnsName, ipnsGateway);
      blobBytes = await fetchFromIpfs(cid, ipfsGateway);
    }

    // Detect version
    if (detectBlobVersion(blobBytes) !== 2) {
      showError(1, 'The vault blob at this IPNS name is not v2 format. Recovery cannot proceed.');
      btn.disabled = false;
      btn.textContent = '[ Start Recovery ]';
      return;
    }

    // Extract and decrypt rootFolderKey from v2 key blob
    const encryptedRootFolderKey = deserializeVaultBlobV2(blobBytes);
    rootFolderKey = await eciesDecrypt(privateKeyBytes, encryptedRootFolderKey);

    btn.disabled = false;
    btn.textContent = '[ Start Recovery ]';

    // Proceed to Step 2 (Recovery Progress)
    showStep(2);

    // Reset state
    recoveredFiles = [];
    fileCount = 0;
    errorCount = 0;
    ipnsFailures = [];
    logEl.innerHTML = '';

    const gatewayConfig = { ipnsGateway, ipfsGateway };

    log('CipherBox Vault Recovery starting...', 'info');
    log(`IPNS gateway: ${ipnsGateway}`, 'info');
    log(`IPFS gateway: ${ipfsGateway}`, 'info');
    log('', 'info');

    try {
      await recoverFolder(directRootFolderIpnsName, rootFolderKey, '', gatewayConfig);

      log('', 'info');
      if (fileCount === 0 && errorCount === 0) {
        log('Recovery complete. Vault is empty (no files found).', 'warn');
      } else if (errorCount === 0) {
        log(`Recovery complete. ${fileCount} file(s) recovered successfully.`, 'success');
      } else {
        log(`Recovery complete. ${fileCount} file(s) recovered, ${errorCount} error(s).`, 'warn');
      }

      // Report IPNS resolution failures with details for manual recovery
      if (ipnsFailures.length > 0) {
        log('', 'info');
        log(`${ipnsFailures.length} file(s) had expired IPNS records:`, 'warn');
        for (const f of ipnsFailures) {
          log(`  - ${f.name} (IPNS: ${truncate(f.ipnsName, 40)})`, 'warn');
        }
        log('These files are still on IPFS but their CIDs cannot be discovered via IPNS.', 'warn');
        log('If you have the CIDs from another source, you can retrieve them manually.', 'info');
      }

      if (fileCount > 0) {
        document.getElementById('btn-download').classList.add('visible');
      }

      document.getElementById('post-note').classList.add('visible');
    } catch (e) {
      log(`FATAL ERROR: ${e.message}`, 'error');
      showError(2, 'Recovery failed: ' + e.message);
      document.getElementById('post-note').classList.add('visible');
    }
  } catch (e) {
    showError(1, 'Error: ' + e.message);
    const btn = document.getElementById('btn-start');
    btn.disabled = false;
    btn.textContent = '[ Start Recovery ]';
  }
});

