  1→/**
  2→ * IPNS Service - Record creation, publishing, and resolution
  3→ *
  4→ * Extracted from: apps/web/src/services/ipns.service.ts
  5→ * Change: Uses @cipherbox/api-client generated functions instead of web app local imports.
  6→ * The ipns.service.ts was already clean (no store deps), so the extraction is straightforward.
  7→ */
  8→
  9→import { createIpnsRecord, marshalIpnsRecord, IPNS_SIGNATURE_PREFIX } from '@cipherbox/core';
 10→import { verifyEd25519, concatBytes } from '@cipherbox/crypto';
 11→import {
 12→  ipnsControllerPublishRecord,
 13→  ipnsControllerPublishBatch,
 14→  ipnsControllerResolveRecord,
 15→} from '@cipherbox/api-client';
 16→import type { PublishIpnsEntryDtoRecordType } from '@cipherbox/api-client';
 17→import type { SdkContext } from '../types';
 18→import { withPerf } from '../perf';
 19→
 20→/**
 21→ * Create an IPNS record locally and publish via backend.
 22→ *
 23→ * The record is signed locally using the Ed25519 private key, then
 24→ * the backend relays it to the IPFS network via delegated routing.
 25→ *
 26→ * @param params.ipnsPrivateKey - Ed25519 private key (64 bytes in libp2p format)
 27→ * @param params.ipnsName - IPNS name (k51.../bafzaa... format)
 28→ * @param params.metadataCid - CID of the encrypted metadata blob
 29→ * @param params.sequenceNumber - Current sequence number (will be incremented before publish)
 30→ * @param params.encryptedIpnsPrivateKey - Hex ECIES-wrapped key for TEE (first publish only)
 31→ * @param params.keyEpoch - TEE key epoch (required with encryptedIpnsPrivateKey)
 32→ * @param params.expectedSequenceNumber - Pre-increment sequence number for conflict detection (folder records only)
 33→ */
 34→export async function createAndPublishIpnsRecord(params: {
 35→  ipnsPrivateKey: Uint8Array;
 36→  ipnsName: string;
 37→  metadataCid: string;
 38→  sequenceNumber: bigint;
 39→  encryptedIpnsPrivateKey?: string;
 40→  keyEpoch?: number;
 41→  expectedSequenceNumber?: string;
 42→  ctx?: SdkContext;
 43→}): Promise<{ success: boolean; sequenceNumber: bigint }> {
 44→  return withPerf('ipns:publish', async () => {
 45→    // 1. Create IPNS record pointing to /ipfs/{metadataCid}
 46→    // 24 hour lifetime (will be republished by TEE every 3 hours)
 47→    const record = await createIpnsRecord(
 48→      params.ipnsPrivateKey,
 49→      `/ipfs/${params.metadataCid}`,
 50→      params.sequenceNumber,
 51→      24 * 60 * 60 * 1000 // 24 hours in ms
 52→    );
 53→
 54→    // 2. Marshal to bytes for transport
 55→    const recordBytes = marshalIpnsRecord(record);
 56→
 57→    // 3. Base64 encode for API transmission (loop-based to avoid call stack overflow on large records)
 58→    let binary = '';
 59→    for (let i = 0; i < recordBytes.length; i++) {
 60→      binary += String.fromCharCode(recordBytes[i]);
 61→    }
 62→    const recordBase64 = btoa(binary);
 63→
 64→    // 4. Call backend API to relay to IPFS network
 65→    const apiOptions = params.ctx?.axiosInstance
 66→      ? { _axiosInstance: params.ctx.axiosInstance }
 67→      : undefined;
 68→    const response = await ipnsControllerPublishRecord(
 69→      {
 70→        ipnsName: params.ipnsName,
 71→        record: recordBase64,
 72→        metadataCid: params.metadataCid,
 73→        encryptedIpnsPrivateKey: params.encryptedIpnsPrivateKey,
 74→        keyEpoch: params.keyEpoch,
 75→        expectedSequenceNumber: params.expectedSequenceNumber,
 76→      },
 77→      apiOptions
 78→    );
 79→
 80→    return {
 81→      success: response.success,
 82→      sequenceNumber: BigInt(response.sequenceNumber),
 83→    };
 84→  });
 85→}
 86→
 87→/**
 88→ * Batch publish multiple IPNS records in a single API call.
 89→ *
 90→ * Sends all records (folder and/or file) to the batch endpoint,
 91→ * which processes them with concurrency-limited parallelism.
 92→ * Partial success is allowed: individual failures do not fail the batch.
 93→ *
 94→ * @param records - Array of IPNS record payloads to publish
 95→ * @returns Success and failure counts
 96→ */
 97→export async function batchPublishIpnsRecords(
 98→  records: Array<{
 99→    ipnsName: string;
100→    recordBase64: string;
101→    metadataCid: string;
102→    encryptedIpnsPrivateKey?: string;
103→    keyEpoch?: number;
104→    recordType?: 'folder' | 'file';
105→    /** Pre-increment sequence number for conflict detection (folder records only) */
106→    expectedSequenceNumber?: string;
107→  }>,
108→  ctx?: SdkContext
109→): Promise<{ totalSucceeded: number; totalFailed: number }> {
110→  return withPerf('ipns:batch-publish', async () => {
111→    const apiOptions = ctx?.axiosInstance ? { _axiosInstance: ctx.axiosInstance } : undefined;
112→    const response = await ipnsControllerPublishBatch(
113→      {
114→        records: records.map((r) => ({
115→          ipnsName: r.ipnsName,
116→          record: r.recordBase64,
117→          metadataCid: r.metadataCid,
118→          encryptedIpnsPrivateKey: r.encryptedIpnsPrivateKey,
119→          keyEpoch: r.keyEpoch,
120→          recordType: r.recordType as PublishIpnsEntryDtoRecordType | undefined,
121→          expectedSequenceNumber: r.expectedSequenceNumber,
122→        })),
123→      },
124→      apiOptions
125→    );
126→
127→    return {
128→      totalSucceeded: response.totalSucceeded,
129→      totalFailed: response.totalFailed,
130→    };
131→  });
132→}
133→
134→/**
135→ * Verify the Ed25519 signature on an IPNS record.
136→ * Per IPFS spec, the signature is over "ipns-signature:" + cborData.
137→ *
138→ * @param signatureV2 - base64 Ed25519 signature (64 bytes)
139→ * @param data - base64 CBOR data that was signed
140→ * @param pubKey - base64 raw Ed25519 public key (32 bytes)
141→ * @returns true if valid
142→ */
143→export async function verifyIpnsSignature(
144→  signatureV2: string,
145→  data: string,
146→  pubKey: string
147→): Promise<boolean> {
148→  const sigBytes = Uint8Array.from(atob(signatureV2), (c) => c.charCodeAt(0));
149→  const dataBytes = Uint8Array.from(atob(data), (c) => c.charCodeAt(0));
150→  const pubKeyBytes = Uint8Array.from(atob(pubKey), (c) => c.charCodeAt(0));
151→
152→  // Per IPFS IPNS spec, signature is over "ipns-signature:" + cborData
153→  const signedData = concatBytes(IPNS_SIGNATURE_PREFIX, dataBytes);
154→  return verifyEd25519(sigBytes, signedData, pubKeyBytes);
155→}
156→
157→/**
158→ * Resolve an IPNS name to its current CID and sequence number.
159→ *
160→ * Calls backend API which relays to the delegated routing service for resolution.
161→ * When the response includes IPNS signature data (from delegated routing),
162→ * verifies the Ed25519 signature before trusting the CID.
163→ *
164→ * @param ipnsName - IPNS name to resolve (k51.../bafzaa... format)
165→ * @returns Current CID, sequence number, and signature verification status, or null if not found
166→ */
167→export async function resolveIpnsRecord(
168→  ipnsName: string,
169→  ctx?: SdkContext
170→): Promise<{ cid: string; sequenceNumber: bigint; signatureVerified: boolean } | null> {
171→  return withPerf('ipns:resolve', async () => {
172→    try {
173→      const apiOptions = ctx?.axiosInstance ? { _axiosInstance: ctx.axiosInstance } : undefined;
174→      const response = await ipnsControllerResolveRecord({ ipnsName }, apiOptions);
175→
176→      if (!response.success) {
177→        return null;
178→      }
179→
180→      // Verify IPNS signature if all signature fields are present
181→      let signatureVerified = false;
182→      if (response.signatureV2 && response.data && response.pubKey) {
183→        const valid = await verifyIpnsSignature(
184→          response.signatureV2,
185→          response.data,
